P = [
 dict(pmid='43010186', doi='10.1016/j.jphotobiol.2026.113461', journal='J Photochem Photobiol B', title='Toxic synergy between wood combustion smoke components and high energy visible light on retinal pigment epithelial cells.', short='Laval retinal pigment epithelium wood smoke extract high-energy visible blue light synergy Nrf2 oxidative stress', design='In vitro cell exposure', pm='Wood combustion smoke extract with high-energy visible light co-exposure', geo='Canada (laboratory)', endpoint='RPE cell viability, oxidative stress, Nrf2 activation', tier='C', basis='Lab / research instrument', affil='CHU de Quebec - Universite Laval, Canada; CHU de Quebec - Universite Laval, Canada', n='Human retinal pigment epithelium cells co-exposed to wood combustion smoke extract and high-energy visible (blue) light. The two acted synergistically to reduce viability through oxidative stress that antioxidant treatment mitigated, implying light-sensitive chromophores among smoke constituents; cells activated Nrf2 detoxification. No doses, extract preparation, or how smoke components would reach the retina in vivo are given in the abstract, and an extract is not deposited particulate matter. The plausible exposure path is ocular surface contact or systemic translocation, neither of which the design addresses; the result is a hazard signal for heavy wood-smoke settings rather than an ambient effect. Relevance: peripheral - extends wood-smoke toxicity to a photosensitisation route; no exposure-measurement content.', sub=corpus.MECH),
 dict(pmid='', doi='10.21203/rs.3.rs-10385808/v2', journal='Research Square', title='The acoustic environment is structured more by place and fine particulate matter more by time across Rhode Island communities', short='Brown Rhode Island 144 sites 531 site-sessions PM2.5 sound night-time illuminance variance place vs time', design='Multi-site monitoring campaign', pm='Short-session PM2.5 measured at 144 sites, day and night, over 39 days', geo='USA (Rhode Island)', endpoint='Variance partition of PM2.5 and sound between sites and days; predictors', tier='B', basis='Not stated', affil='Brown University, USA; Brown University, USA', n='Preprint. PM2.5, sound and night-time illuminance measured at 144 sites in eight Rhode Island municipalities, four day/night session types over 39 days (531 site-sessions). Sound and PM2.5 were uncorrelated and had different predictors: sound rose near industrial land and varied mainly between sites; PM2.5 tracked weather (falling with wind, rising with temperature and precipitation) and varied mainly between days, rising at night. Results held under penalised regression and spatial-cluster adjustment. The instrument is not named, and short sessions at one site per visit confound site with day, which is exactly the decomposition being estimated. Relevance: direct - quantifies how little between-site PM2.5 contrast short mobile campaigns resolve against day-to-day variance.', sub=corpus.EXPO),
 dict(pmid='', doi='10.21203/rs.3.rs-11369151/v1', journal='Research Square', title='Machine Learning-Enhanced Air Quality Management via QFIELD and QGIS: Mapping and Bio-cover Materials at Ojota Landfill', short='Ojota landfill Lagos bio-cover QFIELD QGIS PM2.5 PM10 SO2 CO six ML methods AQI risk surface', design='Pilot field measurement', pm='Point PM2.5 and PM10 at six sampling points 15 m apart, interpolated by ML', geo='Nigeria (Lagos)', endpoint='AQI classification and pollutant risk surface; microbial indicators after bio-cover', tier='C', basis='Not stated', affil='Yaba College of Technology, Nigeria; Yaba College of Technology, Nigeria', n='Preprint. Six geo-referenced sampling points at 15 m spacing across the Ojota landfill, Lagos, measuring PM2.5, PM10, SO2 and CO as baseline, then six machine-learning methods (random forest, gradient boosting, SVM, kNN, Gaussian process/regression kriging, ANN) to classify AQI drivers and produce an uncertainty-aware risk surface; a laboratory bio-cover (topsoil, compost, rice husk, earthworm castings) reduced microbial indicators. No PM concentrations, instrument or model skill are reported in the abstract, and six points cannot support six learned spatial models. Relevance: peripheral - shows the demand for landfill-fenceline PM monitoring in West Africa; the analysis is underpowered.', sub=corpus.EXPO),
 dict(pmid='', doi='10.21203/rs.3.rs-11439350/v1', journal='Research Square', title='LOCATE: Context-Aware GeoAI Decision Support for Population-Oriented Air-Quality Sensor Placement in Data-Constrained Cities', short='AirQo LOCATE GeoAI population-weighted p-median sensor placement Kampala Jinja Nairobi Lagos budgets 5-80', design='Machine-learning model', pm='No PM data: siting by modelled residential population plus OpenStreetMap roads and buildings', geo='Africa (Uganda, Kenya, Nigeria)', endpoint='Population-and-context coverage of candidate low-cost sensor layouts', tier='B', basis='Low-cost sensor / network', affil='Makerere University / AirQo, Uganda; Makerere University / AirQo, Uganda', n='Preprint from the AirQo group. LOCATE is a pre-deployment siting framework for data-constrained cities that prioritises proximity to modelled residential population while adding road and building context. Six feature-informed clustering methods, two allocation methods and two uninformed baselines were compared across Kampala, Jinja, Nairobi and Lagos for budgets of 5-80 sensors (20 seeds). The context-augmented population-weighted p-median ranked first in all four cities; coverage rose with budget but stayed lower in the larger Lagos and Nairobi domains. The authors state the limitation plainly: layouts are shortlists, not evidence of pollution reconstruction or exposure accuracy, because no concentration field enters the objective. Relevance: direct - siting for low-cost PM networks where no reference surface exists.', sub=corpus.SENS),
]
